SELECT * FROM tt_inbox
WHERE inbox_id = #{inboxId}
  AND tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}

SELECT * FROM tt_inbox
WHERE tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND read_at IS NULL
  AND inbox_id < #{cursor}
ORDER BY created_at DESC, inbox_id DESC
LIMIT #{limit}

SELECT COUNT(*) FROM tt_inbox
WHERE tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND read_at IS NULL

mapper.update:
UPDATE tt_inbox SET read_at = #{readAt}
WHERE inbox_id = #{inboxId}
  AND tenant_id = #{tenantId}
  AND recipient_type = #{recipientType}
  AND recipient_id = #{recipientId}
  AND read_at IS NULL
